<template><div class="page-card"><div class="toolbar"><el-button v-if="isAdmin" type="success" @click="visible=true">新增公司</el-button><el-button @click="load">刷新</el-button></div><el-table :data="rows"><el-table-column prop="company_name" label="公司名称"/><el-table-column prop="company_code" label="编码"/><el-table-column prop="role" label="我的角色" width="110"/><el-table-column prop="status" label="状态" width="100"/><el-table-column label="操作" width="120"><template #default="s"><el-button link type="primary" @click="members(s.row)">成员</el-button></template></el-table-column></el-table><el-dialog v-model="visible" title="新增公司" width="520px"><el-form label-width="100px"><el-form-item label="公司名称"><el-input v-model="form.company_name"/></el-form-item><el-form-item label="公司编码"><el-input v-model="form.company_code"/></el-form-item><el-form-item label="说明"><el-input v-model="form.description" type="textarea"/></el-form-item></el-form><template #footer><el-button @click="visible=false">取消</el-button><el-button type="primary" @click="create">保存</el-button></template></el-dialog><el-drawer v-model="memberVisible" title="公司成员" size="60%"><div class="toolbar"><el-select v-model="memberForm.user_id" filterable style="width:260px"><el-option v-for="x in users" :key="x.user_id" :label="`${x.nick_name} (${x.user_name})`" :value="x.user_id"/></el-select><el-select v-model="memberForm.role" style="width:130px"><el-option label="OWNER" value="OWNER"/><el-option label="ADMIN" value="ADMIN"/><el-option label="MEMBER" value="MEMBER"/></el-select><el-button type="primary" @click="saveMember">保存成员</el-button></div><el-table :data="memberRows"><el-table-column prop="user_name" label="账号"/><el-table-column prop="nick_name" label="昵称"/><el-table-column prop="role" label="角色"/><el-table-column label="操作" width="100"><template #default="s"><el-button link type="danger" @click="deleteMember(s.row)">移除</el-button></template></el-table-column></el-table></el-drawer></div></template>
<script setup>import{onMounted,reactive,ref}from'vue';import{ElMessage}from'element-plus';import api from'../api';import{isAdmin}from'../auth';import{loadPlatformContext}from'../context';const rows=ref([]),visible=ref(false),memberVisible=ref(false),current=ref(null),memberRows=ref([]),users=ref([]),form=reactive({company_code:'',company_name:'',description:''}),memberForm=reactive({user_id:null,role:'MEMBER'});async function load(){rows.value=(await api.get('/companies')).data}async function create(){try{await api.post('/companies',form);visible.value=false;ElMessage.success('创建成功');await loadPlatformContext();load()}catch(e){ElMessage.error(e.response?.data?.detail||'创建失败')}}async function members(row){current.value=row;memberRows.value=(await api.get(`/companies/${row.company_id}/members`)).data;users.value=(await api.get(`/companies/${row.company_id}/user-options`)).data;memberVisible.value=true}async function saveMember(){try{await api.put(`/companies/${current.value.company_id}/members`,memberForm);ElMessage.success('保存成功');members(current.value)}catch(e){ElMessage.error(e.response?.data?.detail||'保存失败')}}async function deleteMember(row){try{await api.delete(`/companies/${current.value.company_id}/members/${row.user_id}`);members(current.value)}catch(e){ElMessage.error(e.response?.data?.detail||'移除失败')}}onMounted(load)</script>
